def backfill_mission_orders(apps, schema_editor):
    """Give existing approved missions a meaningful Mission Order state.

    Approved-but-not-dispatched missions are put in the signatory queue using
    their approving authority (or approver) as the designated signatory.
    Already-active or completed missions keep an approved order covering the
    revision they were dispatched under, so historical records do not suddenly
    appear blocked by a workflow they predate.
    """
    from django.utils import timezone

    Mission = apps.get_model("ops", "Mission")
    for mission in Mission.objects.filter(approval_status="approved").iterator():
        signatory_id = mission.approving_authority_id or mission.approved_by_id
        if not signatory_id:
            continue
        if mission.status in {"active", "completed"}:
            Mission.objects.filter(pk=mission.pk).update(
                mission_order_signatory_id=signatory_id,
                mission_order_status="approved",
                mission_order_assigned_at=mission.approved_at,
                mission_order_signed_at=mission.approved_at,
                mission_order_signed_by_id=mission.approved_by_id or signatory_id,
                mission_order_signed_revision=mission.revision,
            )
        else:
            Mission.objects.filter(pk=mission.pk).update(
                mission_order_signatory_id=signatory_id,
                mission_order_status="awaiting_signature",
                mission_order_assigned_at=mission.approved_at or timezone.now(),
            )


